import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t_str = next(iterator)
        T = int(t_str)
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            P = next(iterator)
        except StopIteration:
            break

        n = len(P)
        current_jump = 1
        days = 0
        i = 0

        while i < n - 1:
            if P[i + 1] == '#':
                i += 1
            else:
                gap = 0
                j = i + 1
                while j < n and P[j] == '.':
                    gap += 1
                    j += 1

                if j >= n:
                    break

                required_jump = gap + 1

                if required_jump > current_jump:
                    days += 1
                    current_jump = required_jump

                i = j

        results.append(str(days))

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == "__main__":
    solve()
